 export function parseCliArgs(argv: string[]): MultiCliArgs | null {
   const args = argv.slice(2)
   const parsed: Partial<MultiCliArgs> = {}

   for (let i = 0; i < args.length; i++) {
     const arg = args[i]
     const next = args[i + 1]

     switch (arg) {
       case "--repo-root":
       case "-r":
         if (!next) {
           console.error("Error: --repo-root requires a value")
           return null
         }
         parsed.repoRoot = next
         i++
         break

       case "--stream":
       case "-s":
         if (!next) {
           console.error("Error: --stream requires a value")
           return null
         }
         parsed.streamId = next
         i++
         break

       case "--batch":
       case "-b":
         if (!next) {
           console.error("Error: --batch requires a value")
           return null
         }
         parsed.batch = next
         i++
         break

       case "--continue":
       case "-c":
         parsed.continue = true
         break

       case "--port":
       case "-p":
         if (!next) {
           console.error("Error: --port requires a value")
           return null
         }
         parsed.port = parseInt(next, 10)
         if (isNaN(parsed.port)) {
           console.error("Error: --port must be a number")
           return null
         }
         i++
         break

       case "--dry-run":
         parsed.dryRun = true
         break

       case "--no-server":
         parsed.noServer = true
         break

       case "--headless":
         parsed.headless = true
         break

       case "--async":
         parsed.async = true
         break

       case "--silent":
         parsed.silent = true
         break

       case "--help":
       case "-h":
         printHelp()
         process.exit(0)
     }
   }

   return parsed as MultiCliArgs
 }

