 function normalizeEnum<T extends string>(
   value: unknown,
   allowed: readonly T[],
   path: string,
   errors: ReviewerValidationError[],
 ): T | null {
   if (typeof value !== "string") {
     errors.push({
       path,
       message: "Expected string enum value",
       expected: allowed.join(" | "),
       received: typeof value,
