 /**
  * Create an empty supervisor-state.json structure.
  */
 export function createEmptySupervisorState(streamId: string): SupervisorStateFile {
   return {
     version: SUPERVISOR_STATE_VERSION,
     stream_id: streamId,
     last_updated: new Date().toISOString(),
     runs: [],
     reviewed_batches: [],
     issue_summaries: [],
     fix_cycles: [],
     escalations: [],
     stage_stops: [],
   }
