       if (!synthesisAgent) {
         console.log(`Synthesis agent override "${agentOverride}" not found in agents.yaml, using default`)
         synthesisAgent = getDefaultSynthesisAgent(agentsConfig)
       }
     } else {
       synthesisAgent = getDefaultSynthesisAgent(agentsConfig)
     }

     if (synthesisAgent) {
