     )
     console.error(`\nHint: Make sure tasks.json has tasks for this batch.`)
     process.exit(1)
   }

   if (threads.length > MAX_THREADS_PER_BATCH) {
     console.error(
       `Error: Batch has ${threads.length} threads, but max is ${MAX_THREADS_PER_BATCH}`,
     )
