   if (completions.length === 0) {
     return {
       completedThreadIds: [],
       cleanup: {
         completionMarkers: 0,
         sessionFiles: 0,
         resultFiles: 0,
         synthesisFiles: 0,
       },
     }
   }

   if (verbose) {
