       taskId,
       sessionId,
       status,
       exitCode,
     })),
   )

   const completedThreadIds = Array.from(
     new Set(completions.map((completion) => completion.threadId)),
   )
   const completedMappings = completions.map(({ taskId, threadId, sessionId }) => ({
     taskId,
     threadId,
     sessionId,
     paneId: "",
