 async function runWorkMultiHeadless(args: {
   repoRoot: string
   streamId: string
   batchId: string
   port?: number
   noServer?: boolean
   silent?: boolean
 }): Promise<void> {
   const workCliPath = fileURLToPath(new URL("../../bin/work.ts", import.meta.url))
   const commandArgs = [
     workCliPath,
     "multi",
     "--repo-root",
     args.repoRoot,
     "--stream",
     args.streamId,
     "--batch",
     args.batchId,
     "--headless",
     "--async",
   ]

   if (args.port !== undefined) {
     commandArgs.push("--port", String(args.port))
   }
   if (args.noServer) {
     commandArgs.push("--no-server")
   }
   if (args.silent) {
     commandArgs.push("--silent")
   }

   await new Promise<void>((resolve, reject) => {
     const child = spawn(process.execPath, commandArgs, {
       cwd: args.repoRoot,
       stdio: ["ignore", "pipe", "pipe"],
     })

     let stdout = ""
     let stderr = ""
     child.stdout?.on("data", (chunk) => {
       stdout += chunk.toString()
     })
     child.stderr?.on("data", (chunk) => {
       stderr += chunk.toString()
     })

     child.on("close", (code) => {
       if (code === 0) {
         resolve()
         return
       }

       reject(
         new Error(
           stderr.trim() || stdout.trim() || `work multi exited with status ${code ?? 1}`,
         ),
       )
     })
     child.on("error", reject)
   })
 }

