           stopId: `${resolvedReview.reviewId}-stage-stop`,
           runId,
           stageId,
           batchId: currentBatchId,
           reason: stageBoundary.stopReason ?? "completed",
           summary: stageBoundary.summary,
           stoppedAt: resolvedReview.reviewedAt,
           escalationId,
         })
