           `[supervise] stop: ${stageBoundary.shouldContactUser ? "user input required" : "stage boundary reached"}. ${stageBoundary.summary}`,
         )
         break
       }

       const nextBatchId = findNextBatchId(tasksFile.tasks, currentBatchId)
       if (!nextBatchId) {
