     }

     await recordStageStopLocked(repoRoot, stream.id, {
       stopId: `${runId}-error-stop`,
       runId,
       stageId,
       batchId: currentBatchId ?? undefined,
       reason: "failed",
       summary: `Supervisor run failed: ${(error as Error).message}`,
       stoppedAt: new Date().toISOString(),
