     try {
       const content = readFileSync(targetSettingsPath, "utf-8")
       targetSettings = JSON.parse(content)
     } catch (e) {
       console.error(`${RED}Error reading ${targetSettingsPath}: ${e}${NC}`)
       process.exit(1)
     }
   }

   // Merge hooks into settings
   const mergedSettings = {
