 function hooksCommand(args: string[]): void {
   const targets: string[] = []
   let dryRun = false
   let listOnly = false

   let i = 0
   while (i < args.length) {
     const arg = args[i]
     switch (arg) {
       case "--claude":
         targets.push(HOOKS_TARGETS.claude!)
         break
       case "--list":
         listOnly = true
         break
       case "--dry-run":
         dryRun = true
         break
       case "--help":
       case "-h":
         printHooksHelp()
         process.exit(0)
       default:
         console.error(`${RED}Error: Unknown option: ${arg}${NC}`)
         printHooksHelp()
         process.exit(1)
     }
     i++
   }

   // Handle list mode
   if (listOnly) {
     listHooks()
     return
   }

   // Default to Claude if no targets specified
   if (targets.length === 0) {
     targets.push(HOOKS_TARGETS.claude!)
   }

   // Install to each target
   for (const target of targets) {
     installHooksTo(target, dryRun)
   }
 }

