         targets.push(TARGETS.antigravity)
         break
       case "--opencode":
         targets.push(TARGETS.opencode)
         break
       case "--all":
         targets.push(
           TARGETS.claude,
           TARGETS.codex,
           TARGETS.gemini,
           TARGETS.antigravity,
           TARGETS.opencode,
         )
         break
       case "--target":
