   const terminalBranch = await args.deps.waitForTerminalBranchSession({
     repoRoot: args.repoRoot,
     streamId: args.streamId,
     branchSessionId: args.branchSessionId,
     timeoutMs: 5000,
     pollIntervalMs: 100,
   })

   if (!nativeSessionId) {
     return {
       terminalBranch,
       reportText: "",
