       case "--antigravity":
         targets.push(TARGETS.antigravity)
         break
       case "--opencode":
         targets.push(TARGETS.opencode)
         break
       case "--all":
         targets.push(
           TARGETS.claude,
           TARGETS.codex,
           TARGETS.gemini,
           TARGETS.antigravity,
           TARGETS.opencode,
         )
         break
       case "--target":
         i++
         if (!args[i]) {
           console.error(`${RED}Error: --target requires a path${NC}`)
           process.exit(1)
         }
         targets.push(args[i])
         break
       case "--clean":
         clean = true
         break
       case "--list":
         listOnly = true
         break
       case "--dry-run":
         dryRun = true
         break
       case "--help":
       case "-h":
         printSkillsHelp()
         process.exit(0)
       default:
         console.error(`${RED}Error: Unknown option: ${arg}${NC}`)
         printSkillsHelp()
         process.exit(1)
     }
     i++
   }

   // Handle list mode
   if (listOnly) {
     listSkills()
     return
   }

   // Default to Claude if no targets specified
   if (targets.length === 0) {
     targets.push(TARGETS.claude)
   }

   // Install to each target
   for (const target of targets) {
     if (!target) continue
     installSkillsTo(target, dryRun, clean)
     console.log("")
   }
 }

 export function main(argv: string[]): void {
   const args = argv.slice(2) // Remove 'bun' and 'ag-install'

   if (args.length === 0) {
     printHelp()
     process.exit(0)
   }

   const subcommand = args[0]

   if (subcommand === "--help" || subcommand === "-h") {
     printHelp()
     process.exit(0)
   }

   switch (subcommand) {
     case "skills":
       skillsCommand(args.slice(1))
       break
     case "hooks":
       hooksCommand(args.slice(1))
       break
     case "plugins":
       pluginsCommand(args.slice(1))
       break
     case "tools":
       toolsCommand(args.slice(1))
       break
     case "commands":
       commandsCommand(args.slice(1))
       break
     default:
       console.error(`Error: Unknown subcommand "${subcommand}"`)
       console.error("\nAvailable subcommands: skills, hooks, plugins, tools, commands")
       console.error("\nRun 'ag install --help' for usage information.")
       process.exit(1)
   }
 }

