   const scope = args.scope ?? args.fallbackScope
   const fallbackBatchId =
     args.fallbackScope?.level === "batch" ? args.fallbackScope.batchId : undefined
   const scopeBatchId = scope?.level === "batch" ? scope.batchId : undefined
